import{_ as t,o,c as a,a2 as l}from"./chunks/framework.D66Xq0Kv.js";const w=JSON.parse('{"title":"CC Switch 接入 OpenClaw：AI 私人助理也能用中转站","description":"","frontmatter":{"title":"CC Switch 接入 OpenClaw：AI 私人助理也能用中转站","date":"2026-09-18T20:00:00.000Z","tags":["CC Switch","OpenClaw","中转站","教程"],"categories":["技术折腾"]},"headers":[],"relativePath":"guide/06-openclaw.md","filePath":"guide/06-openclaw.md"}'),n={name:"guide/06-openclaw.md"};function i(r,e,c,s,p,d){return o(),a("div",null,[...e[0]||(e[0]=[l('<blockquote><p>生命不息，折腾不止。</p></blockquote><p>OpenClaw 是一个开源的 AI 私人助理框架（社区里管它叫&quot;能接管你电脑的 AI 管家&quot;）。这篇教小白：用 CC Switch 把 AI 中转站接进 OpenClaw，让它用上你的中转站模型。</p><h2 id="一、openclaw-是什么" tabindex="-1">一、OpenClaw 是什么 <a class="header-anchor" href="#一、openclaw-是什么" aria-label="Permalink to &quot;一、OpenClaw 是什么&quot;">​</a></h2><p>OpenClaw 是开源的 AI 助理框架，可以接入各种大模型，帮你操作电脑、调用工具。它支持一堆模型供应商（DeepSeek、智谱 GLM、通义千问 Qwen、Kimi、MiniMax 等），配置在 <code>opencode.json</code> / Clawdbot 相关配置里——<strong>CC Switch 帮你一键管理</strong>。</p><h2 id="二、准备工作" tabindex="-1">二、准备工作 <a class="header-anchor" href="#二、准备工作" aria-label="Permalink to &quot;二、准备工作&quot;">​</a></h2><blockquote></blockquote><ol><li><strong>中转站 API Key</strong>：后台 → API Keys → 创建，复制 <code>sk-</code> Key</li><li><strong>Node.js</strong>：nodejs.org 装 LTS 版</li><li><strong>安装 OpenClaw</strong>：按 OpenClaw 官方文档安装（GitHub 提供一键脚本）</li><li><strong>下载 CC Switch</strong>：官网 ccswitch.io 或 GitHub Releases</li></ol><h2 id="三、在-cc-switch-里添加-openclaw-供应商" tabindex="-1">三、在 CC Switch 里添加 OpenClaw 供应商 <a class="header-anchor" href="#三、在-cc-switch-里添加-openclaw-供应商" aria-label="Permalink to &quot;三、在 CC Switch 里添加 OpenClaw 供应商&quot;">​</a></h2><ol><li>打开 CC Switch</li><li>左侧切换器选 <strong>OpenClaw</strong> 应用</li><li>点右上角 <strong>+</strong></li><li>预设选 <strong>自定义</strong>，或者选现成的（DeepSeek / 智谱 GLM / Qwen Coder / Kimi 等，看你中转站/直连哪个）</li><li>填关键信息： <ul><li><strong>名称</strong>：如 <code>我的中转站</code></li><li><strong>API 地址（Base URL）</strong>：<code>https://ai.aklibk.com/v1</code></li><li><strong>API Key</strong>：粘贴中转站 Key</li><li><strong>模型</strong>：填一个支持的模型名</li></ul></li><li>点 <strong>添加</strong></li></ol><blockquote></blockquote><blockquote><p>选预设的话只需要填 API Key，端点自动填好，最省事。</p></blockquote><h2 id="四、切换并启动-openclaw" tabindex="-1">四、切换并启动 OpenClaw <a class="header-anchor" href="#四、切换并启动-openclaw" aria-label="Permalink to &quot;四、切换并启动 OpenClaw&quot;">​</a></h2><ol><li>在 OpenClaw 面板点一下刚添加的供应商（选中）</li><li>启动 OpenClaw，问一句&quot;你好&quot;</li></ol><blockquote></blockquote><p>——能回复就成功了</p><p><strong>想换模型/换供应商？</strong> 回 CC Switch 点一下，立刻切换。</p><h2 id="五、常见问题" tabindex="-1">五、常见问题 <a class="header-anchor" href="#五、常见问题" aria-label="Permalink to &quot;五、常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>解决</th></tr></thead><tbody><tr><td>报 401</td><td>API 地址或 Key 填错</td></tr><tr><td>报模型不存在</td><td>换中转站后台实际提供的模型名</td></tr><tr><td>OpenClaw 启动失败</td><td>看 OpenClaw 日志；确认 Node.js 版本 ≥ 18</td></tr></tbody></table><h2 id="六、总结" tabindex="-1">六、总结 <a class="header-anchor" href="#六、总结" aria-label="Permalink to &quot;六、总结&quot;">​</a></h2><p>OpenClaw 接中转站：<strong>下载 CC Switch → OpenClaw 面板添加（填地址+Key）→ 切换 → 启动 OpenClaw</strong>。</p><p>想让你的 AI 管家用上全家桶模型？试试 Aklibk API 中转站（ai.aklibk.com），国内直连、免绑卡、人民币按量付费。</p><blockquote><p>下一篇预告：Hermes——你的 AI 智能体助手，CC Switch 也能管它的配置。</p></blockquote>',22)])])}const C=t(n,[["render",i]]);export{w as __pageData,C as default};
